private static bool IsValid(char[][] board, int row, int col, char digit)
{
    for (int i = 0; i < 9; i++)
    {
        if (board[row][i] == digit) return false;   // row
        if (board[i][col] == digit) return false;   // column
    }

    int boxRow = (row / 3) * 3;
    int boxCol = (col / 3) * 3;

    for (int r = boxRow; r < boxRow + 3; r++)
    for (int c = boxCol; c < boxCol + 3; c++)
    {
        if (board[r][c] == digit) return false;
    }

    return true;
}

public void SolveSudoku(char[][] board)
{
    var rows = new int[9];
    var cols = new int[9];
    var boxes = new int[9];

    // Seed the masks with the given digits
    for (int r = 0; r < 9; r++)
    for (int c = 0; c < 9; c++)
    {
        if (board[r][c] == '.') continue;

        int bit = 1 << (board[r][c] - '1');
        rows[r] |= bit;
        cols[c] |= bit;
        boxes[BoxIndex(r, c)] |= bit;
    }

    Solve();

    bool Solve()
    {
        // Find the first empty cell
        int row = -1, col = -1;
        for (int r = 0; r < 9 && row == -1; r++)
        for (int c = 0; c < 9; c++)
        {
            if (board[r][c] == '.') { row = r; col = c; break; }
        }

        if (row == -1) return true;  // no empty cells left: solved

        int box = BoxIndex(row, col);
        int used = rows[row] | cols[col] | boxes[box];

        for (int digit = 0; digit < 9; digit++)
        {
            int bit = 1 << digit;
            if ((used & bit) != 0) continue;   // digit already in this row, column, or box

            board[row][col] = (char)('1' + digit);
            rows[row] |= bit;
            cols[col] |= bit;
            boxes[box] |= bit;

            if (Solve()) return true;

            // Backtrack: clear the digit from cell and masks
            board[row][col] = '.';
            rows[row] &= ~bit;
            cols[col] &= ~bit;
            boxes[box] &= ~bit;
        }

        return false;  // no digit fits here - the earlier choice was wrong
    }
}

private static int BoxIndex(int row, int col) => (row / 3) * 3 + (col / 3);

public void SolveSudoku(char[][] board)
{
    var rows = new int[9];
    var cols = new int[9];
    var boxes = new int[9];

    for (int r = 0; r < 9; r++)
    for (int c = 0; c < 9; c++)
    {
        if (board[r][c] == '.') continue;
        int bit = 1 << (board[r][c] - '1');
        rows[r] |= bit;
        cols[c] |= bit;
        boxes[(r / 3) * 3 + c / 3] |= bit;
    }

    Solve();

    bool Solve()
    {
        int row = -1, col = -1;
        for (int r = 0; r < 9 && row == -1; r++)
        for (int c = 0; c < 9; c++)
            if (board[r][c] == '.') { row = r; col = c; break; }

        if (row == -1) return true;

        int box = (row / 3) * 3 + col / 3;
        int used = rows[row] | cols[col] | boxes[box];

        for (int digit = 0; digit < 9; digit++)
        {
            int bit = 1 << digit;
            if ((used & bit) != 0) continue;

            board[row][col] = (char)('1' + digit);
            rows[row] |= bit; cols[col] |= bit; boxes[box] |= bit;

            if (Solve()) return true;

            board[row][col] = '.';
            rows[row] &= ~bit; cols[col] &= ~bit; boxes[box] &= ~bit;
        }

        return false;
    }
}
